local base = ed.ui.basescene
local CupArenaMatchBaseScene = newclass(base.mt)
ed.ui.CupArenaMatchBaseScene = CupArenaMatchBaseScene

function CupArenaMatchBaseScene.create(module)
  local self = base.create(module)
  setmetatable(self, CupArenaMatchBaseScene.mt)
  return self
end

function CupArenaMatchBaseScene:initUI()
  local container, ui = ed.editorui(ed.uieditor.CupArenaMatchBaseScene, {
    container = self.mainLayer
  })
  self.baseContainer = container
  self.baseui = ui
  local pigeonFca = ed.createFcaNode("eff_UI_Main_Cuparena_pigeon")
  self:addFca(pigeonFca)
  pigeonFca:setPosition(ccpAdd(ed.display.center, ccp(-ed.display.halfFixedWidth, -ed.display.halfFixedHeight)))
  self.baseui.panel_content:addChild(pigeonFca, -1)
  self:setBackButton(function()
    ed.playEffect(ed.sound.common.back)
  end)
  self:setBackground("UI/alpha/1080P/cuparena/selection/cuparena_selection_bg_3.png")
  local titleBg, titleTxt = ed.UITool.createSceneTitle(T("\229\165\179\231\165\158\228\185\139\230\136\152"), self.baseui.bg_title, {
    position = ccp(20, 18)
  })
  local posX = titleTxt:getPositionX() + titleBg:getContentSize().width * 0.5 + 20
  self.baseui.titleBg = titleBg
  self.baseui.titleTxt = titleTxt
  local ruleWidth = self.baseui.btn_rule:getContentSize().width
  self.baseui.btn_rule:setPositionX(posX + ruleWidth * 0.5)
  posX = posX + ruleWidth + 10
  local zoomLabel = ed.ui.gradientLabel.create({
    text = T("\232\181\155\229\140\186\239\188\154\231\172\172%s\232\181\155\229\140\186", ed.CupArenaManager:getZoneId()),
    fontSize = 15,
    fontName = ed.font,
    startColor = ed.toccc3(16773995),
    endColor = ed.toccc3(16776911),
    strokeSize = 1,
    strokeColor = ed.toccc3(8803621)
  }).node
  self.baseui.bg_title:addChild(zoomLabel)
  zoomLabel:setAnchorPoint(ccp(0, 0.5))
  zoomLabel:setPosition(ccp(posX, 18))
  posX = posX + zoomLabel:getContentSize().width + 25
  self.baseui.bg_title:setContentSize(CCSizeMake(posX, 35.5))
  self.baseui.zoomLabel = zoomLabel
  ed.setLabelStroke(self.baseui.label_honor, ed.toccc3(2565412), 1)
  ed.setLabelStroke(self.baseui.label_rank, ed.toccc3(2565412), 1)
  ed.setLabelStroke(self.baseui.label_reward, ed.toccc3(2565412), 1)
  ed.setLabelStroke(self.baseui.label_record, ed.toccc3(2565412), 1)
  ed.setLabelStroke(self.baseui.label_grades, ed.toccc3(2565412), 1)
  ed.setLabelStroke(self.baseui.label_timeline, ed.toccc3(2565412), 1)
  self:refreshRecordRedPoint()
  self:refreshRewardRedPoint()
end

function CupArenaMatchBaseScene:adaptUI()
  ed.layout.layoutWithMagin(self.baseui.bg_title, {left = 50, top = 18})
  local localDesignScale = 2.1666666666666665
  local localFixedWidth = ed.display.designSize.height * localDesignScale - ed.display.designSize.width
  local adaptRatio = math.min(ed.display.halfFixedWidth * 2 / localFixedWidth, 1)
  ed.layout.layoutWithMagin(self.baseui.panel_left, {
    left = adaptRatio * 45 - 5
  })
  ed.layout.layoutWithMagin(self.baseui.panel_right, {right = -5})
end

function CupArenaMatchBaseScene:registerBtn(btn, func, params)
  local config = {
    button = btn,
    key = key,
    clickHandler = function(_, x, y)
      ed.playEffect(ed.sound.deo.common_back)
      func(x, y)
    end,
    force = true,
    mcpMode = true,
    mcp_dis = 30,
    clickInterval = 0.3,
    priority = -1
  }
  for k, v in pairs(params or {}) do
    config[k] = v
  end
  self:btRegisterButtonClick(config)
end

function CupArenaMatchBaseScene:registerTouchEvents()
  self:registerBtn(self.baseui.btn_rule, function()
    self:onRuleEvent()
  end, {pressScale = 0.95})
  self:registerBtn(self.baseui.btn_honor, function()
    self:onHonorEvent()
  end, {normalScale = 0.9, pressScale = 0.81})
  self:registerBtn(self.baseui.btn_rank, function()
    self:onRankEvent()
  end, {normalScale = 0.9, pressScale = 0.81})
  self:registerBtn(self.baseui.btn_reward, function()
    self:onRewardEvent()
  end, {normalScale = 0.9, pressScale = 0.81})
  self:registerBtn(self.baseui.btn_record, function()
    self:onRecordEvent()
  end, {normalScale = 0.9, pressScale = 0.81})
  self:registerBtn(self.baseui.btn_grades, function()
    self:onHistoryEvent()
  end, {normalScale = 0.9, pressScale = 0.81})
  self:registerBtn(self.baseui.btn_timeline, function()
    self:onTimelineEvent()
  end, {normalScale = 0.9, pressScale = 0.81})
end

function CupArenaMatchBaseScene:registerEvents()
  self:listenEvent("EventCupArenaMedalRewardRed", function()
    self:refreshRewardRedPoint()
  end)
  self:listenEvent("EventCupArenaChalleneRecordRed", function()
    self:refreshRecordRedPoint()
  end)
end

function CupArenaMatchBaseScene:onEnter(...)
  base.onEnter(self)
end

function CupArenaMatchBaseScene:playEnterAction()
  local lightLayer = CCLayerColor:create(ccc4(255, 255, 255, 255))
  self.mainLayer:addChild(lightLayer, 999)
  lightLayer:runAction(CCEaseIn:create(CCFadeOut:create(0.8333), 2))
  lightLayer:setPosition(-ed.display.halfFixedWidth, -ed.display.halfFixedHeight)
  self.mainLayer:setScale(1.03)
  self.mainLayer:runAction(CCScaleTo:create(0.3333, 1))
  local leftBtnArr = {
    self.baseui.btn_honor,
    self.baseui.btn_rank,
    self.baseui.btn_reward,
    self.baseui.btn_record,
    self.baseui.btn_grades,
    self.baseui.btn_timeline
  }
  for i, v in ipairs(leftBtnArr) do
    v:setCascadeOpacityEnabled(true)
    v:setOpacity(0)
    v:runAction(CCSequence:createWithTwoActions(CCDelayTime:create(0.3333), CCFadeIn:create(0.5)))
  end
  self.baseui.bg_title:setOpacity(0)
  self.baseui.bg_title:runAction(CCSequence:createWithTwoActions(CCDelayTime:create(0.3333), CCFadeIn:create(0.5)))
  self.baseui.titleBg:setOpacity(0)
  self.baseui.titleBg:runAction(CCSequence:createWithTwoActions(CCDelayTime:create(0.3333), CCFadeIn:create(0.5)))
  self.baseui.titleTxt:setOpacity(0)
  self.baseui.titleTxt:runAction(CCSequence:createWithTwoActions(CCDelayTime:create(0.3333), CCFadeIn:create(0.5)))
  self.baseui.btn_rule:setCascadeOpacityEnabled(true)
  self.baseui.btn_rule:setOpacity(0)
  self.baseui.btn_rule:runAction(CCSequence:createWithTwoActions(CCDelayTime:create(0.3333), CCFadeIn:create(0.5)))
  self.back_button:setCascadeOpacityEnabled(true)
  self.back_button:setOpacity(0)
  self.back_button:runAction(CCSequence:createWithTwoActions(CCDelayTime:create(0.3333), CCFadeIn:create(0.5)))
end

