function CupArenaMatchBaseScene:onHonorEvent(...)
  local season = ed.CupArenaManager:getCurrentSeason() or 1
  local scheduleTable = ed.getDataTable("CupArenaSchedule")[ed.CupArenaManager:getScheduleId()]
  if scheduleTable["State Type"] ~= "ShowTime" then
    season = math.max(season - 1, 1)
  end
  ed.CupArenaNetwork:sendTopRankboard(season, 0)
end

function CupArenaMatchBaseScene:onRankEvent(...)
  ed.UITool.openView("CupArenaRankRewardPop", {page = "rank"})
end

function CupArenaMatchBaseScene:onRewardEvent(...)
  ed.UITool.openView("CupArenaRankRewardPop", {page = "reward"})
end

function CupArenaMatchBaseScene:onRecordEvent(...)
  ed.CupArenaNetwork:sendGetBattleRecord(self.identity == "CupArenaKnockoutChallengeScene", true)
end

function CupArenaMatchBaseScene:onHistoryEvent(...)
  ed.CupArenaNetwork:sendHistory()
end

function CupArenaMatchBaseScene:onTimelineEvent(...)
  ed.CupArenaNetwork:sendTimeline()
end

function CupArenaMatchBaseScene:addContentNode(contentNode)
  self.baseui.panel_content:addChild(contentNode)
end

function CupArenaMatchBaseScene:refreshRewardRedPoint()
  self.baseui.img_reward_red:setVisible(ed.CupArenaManager:getMedalRewardRedFlag())
end

function CupArenaMatchBaseScene:refreshRecordRedPoint()
  self.baseui.img_record_red:setVisible(ed.CupArenaManager:getChallengeRecordRedFlag())
end
